mapper.select:
FROM (SELECT p.id FROM posts p
AND p.id < #{cursor}
ORDER BY p.id DESC LIMIT #{limit}) t JOIN posts p ON p.id = t.id JOIN post_categories c ON c.id = p.category_id ORDER BY p.id DESC

mapper.update:
UPDATE posts
   SET view_count = view_count + 1
 WHERE id = #{postId}

UPDATE posts
   SET category_id = #{categoryId},
       title = #{title},
       content = #{content}
 WHERE id = #{postId}

UPDATE posts
   SET status = 'DELETED'
 WHERE id = #{postId}

UPDATE comments
   SET status = 'DELETED'
 WHERE id = #{commentId}

mapper.select:
SELECT EXISTS(
    SELECT 1
      FROM post_reports
     WHERE post_id = #{postId}
       AND reporter_id = #{reporterId}
)

SELECT EXISTS(
    SELECT 1
      FROM post_likes
     WHERE post_id = #{postId}
       AND member_id = #{memberId}
)

mapper.delete:
DELETE FROM post_likes
 WHERE post_id = #{postId}
   AND member_id = #{memberId}

mapper.update:
UPDATE posts
   SET like_count = like_count + #{delta}
 WHERE id = #{postId}

mapper.select:
SELECT like_count
  FROM posts
 WHERE id = #{postId}

mapper.update:
UPDATE posts
   SET status = 'BLOCKED',
       blocked_at = CURRENT_TIMESTAMP(6),
       blocked_reason = #{reason},
       blocked_by = #{adminId}
 WHERE id = #{postId}

mapper.select:
SELECT member_id AS memberId, COUNT(*) AS count FROM posts WHERE status = 'ACTIVE' AND member_id IN
#{memberId}
GROUP BY member_id
